// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Typed errors, exit codes, what-why-fix messages (English + Vietnamese)
// Flo: error set > map error to exit code 0-4 > map error to 3-line message in the chosen language
// I/O: anyerror + lang code (caller) > u8 exit code + Mesg (stderr text)
// ===================================================================
const std = @import("std");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .drif = 3, .bloc = 4 };
pub const Erro = error{ BadUsage, BadConfig, Drift, Halted, CapHit, QuietHour, NeedApprove, NeedLogin, Paused, NoBrowser, BrowFail, Timeout, Closed, TooBig, BadFrame, BadHandshake, CdpError, EvalFail, NoElement, NoJob, Dupe, NavFail, SqliOpen, SqliExec, SqliPrep, SqliBind, SqliStep, AiFail, NoConsent, Locked, Unsafe, WaitTimeout, BadFlow, Fail };
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.NoJob, error.BadConfig, error.BadFlow => CF.usag, error.Drift, error.NoElement => CF.drif, error.Halted, error.CapHit, error.QuietHour, error.NeedApprove, error.NeedLogin, error.Paused, error.NoConsent, error.Locked, error.Unsafe, error.WaitTimeout => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return mesgLang(erro, "en"); }
pub fn mesgLang(erro: anyerror, lang: []const u8) Mesg { if (std.mem.eql(u8, lang, "vi")) return mesgVi(erro); return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: fb-face-webs help" }, error.NoJob => .{ .what = "unknown job", .whyz = "no such job name", .fixz = "run: fb-face-webs jobs" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad value", .fixz = "fix the key or delete the file for defaults" }, error.BadFlow => .{ .what = "bad routine", .whyz = "no routine with that name, or it has no jobs", .fixz = "check flow_list in aa-conf-main.json" }, error.Drift => .{ .what = "page changed", .whyz = "the page does not look as expected", .fixz = "run: fb-face-webs doctor, then check the labels" }, error.Halted => .{ .what = "stopped by Facebook", .whyz = "checkpoint, captcha, 2FA, warning or block seen", .fixz = "open Facebook yourself, clear it, then run: fb-face-webs login" }, error.Unsafe => .{ .what = "stopped for safety", .whyz = "Facebook limited or warned the account", .fixz = "do nothing for 24 hours, then run again at a slow pace" }, error.CapHit => .{ .what = "daily limit reached", .whyz = "this action hit its cap for now", .fixz = "wait, or raise the capz_* key in aa-conf-main.json (slowly)" }, error.QuietHour => .{ .what = "quiet hours", .whyz = "no activity during quiet hours", .fixz = "run later, or change quie_hour_rang" }, error.NeedApprove => .{ .what = "needs your approval", .whyz = "risky action (new person, friend request, delete)", .fixz = "run: fb-face-webs plan, then fb-face-webs approve all (or re-run with --live --force)" }, error.NeedLogin => .{ .what = "not logged in", .whyz = "Facebook shows a login page", .fixz = "run: fb-face-webs login, log in by hand in the window" }, error.NoConsent => .{ .what = "no consent on file", .whyz = "live runs need your OK about the Facebook rules risk", .fixz = "run: fb-face-webs setup" }, error.Locked => .{ .what = "already running", .whyz = "another fb-face-webs run uses this profile", .fixz = "wait for it to finish" }, error.WaitTimeout => .{ .what = "waited too long", .whyz = "the step that needs you was not finished in time", .fixz = "finish it in the browser, then run again" }, error.Paused => .{ .what = "paused", .whyz = "pause flag is set", .fixz = "run: fb-face-webs resume" }, error.NoBrowser => .{ .what = "no browser", .whyz = "Chrome or Edge not found", .fixz = "install Chrome, or set brow_exec_path" }, error.BrowFail => .{ .what = "browser failed", .whyz = "the browser did not start or closed", .fixz = "close other windows using the fb profile, retry" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer in time", .fixz = "retry; raise brow_time_seco if it repeats" }, error.NoElement => .{ .what = "button or box not found", .whyz = "label not on the page", .fixz = "run: fb-face-webs doctor, then fix labl_over in your language" }, error.Dupe => .{ .what = "already done", .whyz = "same action was done before", .fixz = "nothing to do, or run: fb-face-webs unlock <key>" }, error.AiFail => .{ .what = "AI unavailable", .whyz = "Claude CLI and llama.cpp failed, or the daily AI cap is used", .fixz = "templates are used instead" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
fn mesgVi(erro: anyerror) Mesg { return switch (erro) { error.BadUsage => .{ .what = "sai lệnh", .whyz = "lệnh hoặc cờ không đúng", .fixz = "chạy: fb-face-webs help" }, error.NoJob => .{ .what = "không có việc này", .whyz = "tên việc không tồn tại", .fixz = "chạy: fb-face-webs jobs" }, error.BadConfig => .{ .what = "cấu hình sai", .whyz = "aa-conf-main.json có giá trị sai", .fixz = "sửa khóa đó hoặc xóa tệp để dùng mặc định" }, error.BadFlow => .{ .what = "quy trình sai", .whyz = "không có quy trình tên này hoặc chưa có việc nào", .fixz = "kiểm tra flow_list trong aa-conf-main.json" }, error.Drift => .{ .what = "trang đã đổi", .whyz = "trang không giống như dự kiến", .fixz = "chạy: fb-face-webs doctor, rồi kiểm tra nhãn" }, error.Halted => .{ .what = "Facebook đã chặn", .whyz = "gặp kiểm tra bảo mật, captcha, 2FA, cảnh báo hoặc chặn", .fixz = "tự mở Facebook, xử lý xong, rồi chạy: fb-face-webs login" }, error.Unsafe => .{ .what = "dừng để an toàn", .whyz = "Facebook đã hạn chế hoặc cảnh báo tài khoản", .fixz = "nghỉ 24 giờ, rồi chạy lại ở nhịp chậm" }, error.CapHit => .{ .what = "hết hạn mức hôm nay", .whyz = "việc này đã chạm mức tối đa", .fixz = "chờ, hoặc tăng khóa capz_* (từ từ)" }, error.QuietHour => .{ .what = "giờ nghỉ", .whyz = "không hoạt động trong giờ nghỉ", .fixz = "chạy lại sau, hoặc đổi quie_hour_rang" }, error.NeedApprove => .{ .what = "cần bạn duyệt", .whyz = "việc rủi ro (người mới, kết bạn, xóa)", .fixz = "chạy: fb-face-webs plan, rồi fb-face-webs approve all (hoặc chạy lại với --live --force)" }, error.NeedLogin => .{ .what = "chưa đăng nhập", .whyz = "Facebook đang hiện trang đăng nhập", .fixz = "chạy: fb-face-webs login, rồi tự đăng nhập trong cửa sổ" }, error.NoConsent => .{ .what = "chưa có xác nhận", .whyz = "chạy thật cần bạn đồng ý về rủi ro với luật Facebook", .fixz = "chạy: fb-face-webs setup" }, error.Locked => .{ .what = "đang chạy", .whyz = "một lần chạy fb khác đang dùng hồ sơ này", .fixz = "chờ nó chạy xong" }, error.WaitTimeout => .{ .what = "chờ quá lâu", .whyz = "bước cần bạn chưa xong kịp lúc", .fixz = "làm xong trong trình duyệt, rồi chạy lại" }, error.Paused => .{ .what = "đang tạm dừng", .whyz = "cờ tạm dừng đang bật", .fixz = "chạy: fb-face-webs resume" }, error.NoBrowser => .{ .what = "không có trình duyệt", .whyz = "không tìm thấy Chrome hoặc Edge", .fixz = "cài Chrome, hoặc đặt brow_exec_path" }, error.BrowFail => .{ .what = "trình duyệt lỗi", .whyz = "trình duyệt không mở được hoặc bị đóng", .fixz = "đóng các cửa sổ dùng hồ sơ fb, thử lại" }, error.Timeout => .{ .what = "quá giờ", .whyz = "không có phản hồi kịp lúc", .fixz = "thử lại; tăng brow_time_seco nếu lặp lại" }, error.NoElement => .{ .what = "không thấy nút hoặc ô", .whyz = "nhãn không có trên trang", .fixz = "chạy: fb-face-webs doctor, rồi sửa labl_over theo ngôn ngữ của bạn" }, error.Dupe => .{ .what = "đã làm rồi", .whyz = "việc này đã được làm trước đó", .fixz = "không cần làm lại, hoặc chạy: fb-face-webs unlock <khóa>" }, error.AiFail => .{ .what = "AI không dùng được", .whyz = "Claude CLI và llama.cpp lỗi, hoặc hết hạn mức AI trong ngày", .fixz = "sẽ dùng mẫu có sẵn" }, else => .{ .what = "thất bại", .whyz = @errorName(erro), .fixz = "chạy lại với --json và xem status" } }; }
